// Port of main.py input checks + routing.py heuristics (is_broad_contract_search, classify_question).
const cfg = $('Config').first().json;
const body = $('Webhook').first().json.body || {};
const question = typeof body.question === 'string' ? body.question : '';

let error = null;
if (!question.trim()) error = 'question must not be blank';
else if (question.length > Number(cfg.maxQuestionChars)) error = 'question exceeds MAX_QUESTION_CHARS';

const PROJECT_ID = /\b\d{7}(?:\.[A-Za-z0-9]+)?\b/;
const RECENT_YEARS = /\b(?:last|past)\s+\d+\s+years?\b/;
const has = (text, terms) => terms.some((t) => text.includes(t));

function isBroadContractSearch(q) {
  const n = q.toLowerCase();
  return !PROJECT_ID.test(q) && has(n, [
    'find contracts where', 'find all contracts', 'where we have done',
    'past performance', 'scope of work',
  ]);
}

// Deterministic fallback used when the LLM router fails or returns an invalid route.
function classifyQuestion(q) {
  const n = q.toLowerCase().trim();
  if (['hi', 'hello', 'hey', 'good morning', 'good afternoon'].includes(n)) return 'llm_only';
  const asksForContent = has(n, ['summarize', 'summary', 'risk', 'what does', 'explain', 'say about']);
  if (asksForContent && PROJECT_ID.test(q)) return 'sql_and_docs_all';
  if (has(n, ['how do i', 'how do you', 'how to', 'policy', 'procedure', 'guidance', 'manual', 'salesforce'])) {
    return 'reference_docs';
  }
  if (n.includes('base contract')) return asksForContent ? 'sql_and_docs_base' : 'sql_only';
  if (RECENT_YEARS.test(n) && has(n, ['contract', 'capability', 'integration', 'sow', 'pws', 'performance'])) {
    return 'sql_and_docs_base';
  }
  if (asksForContent || has(n, [
    'have we ever', 'capability', 'supporting', 'scope of work', 'past performance',
    'statement of work', 'sow', 'pws', 'find all contracts', 'where we have done',
  ])) return 'docs_only';
  if (has(n, ['contract', 'project', 'opportunit', 'pipeline', 'modified'])) return 'sql_only';
  return 'llm_only';
}

const routerSystem =
  'Classify the question into exactly one route and return only JSON: ' +
  '{"route":"sql_only|sql_and_docs_all|sql_and_docs_base|docs_only|reference_docs|llm_only"}. ' +
  'sql_only is for structured attributes, lists, counts, dates, or opportunity data. ' +
  'sql_and_docs_all requires document content after filtering with a specific project identifier. ' +
  'sql_and_docs_base requires document content after filtering by metadata without a specific ' +
  'project ID, such as a date range. ' +
  'docs_only is broad contract-document content search, including past-performance, capability, ' +
  'SOW/PWS, and opportunity-scope matching. reference_docs is company how-to, Salesforce, policy, ' +
  'or manual guidance. llm_only needs no internal data.';

const valid = error === null;
return [{
  json: {
    valid,
    error,
    question,
    skipRouter: valid && isBroadContractSearch(question) && !RECENT_YEARS.test(question.toLowerCase()),
    fallbackRoute: valid ? classifyQuestion(question) : null,
    llmRequest: {
      model: cfg.routerModel,
      messages: [
        { role: 'system', content: routerSystem },
        { role: 'user', content: question },
      ],
      temperature: 0,
    },
  },
}];

// Port of RouteClassifier.classify: take the LLM's route if valid, otherwise the heuristic fallback.
const pre = $('Validate & Pre-route').first().json;
const ROUTES = ['sql_only', 'sql_and_docs_all', 'sql_and_docs_base', 'docs_only', 'reference_docs', 'llm_only'];

let route = null;
let routeSource = 'llm';
if (pre.skipRouter) {
  route = 'docs_only';
  routeSource = 'heuristic:broad_contract_search';
} else {
  try {
    const content = String($input.first().json.choices[0].message.content);
    const match = content.replace(/```(?:json)?/gi, '').match(/\{[\s\S]*\}/);
    const parsed = JSON.parse(match ? match[0] : content);
    if (ROUTES.includes(parsed.route)) route = parsed.route;
  } catch (e) {
    // fall through to heuristic
  }
  if (!route) {
    route = pre.fallbackRoute;
    routeSource = 'heuristic:fallback';
  }
}

const q = pre.question;
const lower = q.toLowerCase();
let routeGroup = 'llm';
if (route.startsWith('sql')) routeGroup = 'sql';
else if (route === 'docs_only' || route === 'reference_docs') routeGroup = 'docs';

// Entity selection mirrors Workflow.query_structured / query_contracts.
const entity = route === 'sql_only' && (lower.includes('opportunit') || lower.includes('pipeline'))
  ? 'opportunities'
  : 'contract_metadata';
const recent = q.match(/\b(?:last|past)\s+(\d+)\s+years?\b/i);

return [{
  json: {
    question: q,
    route,
    routeSource,
    routeGroup,
    entity,
    baseOnly: lower.includes('base contract'),
    recentYears: recent ? parseInt(recent[1], 10) : null,
  },
}];

// Port of postgres/catalog.py + QueryPlanner.plan prompt.
const cfg = $('Config').first().json;
const ctx = $input.first().json;

const CONTRACT_COLUMNS = [
  'Project_ID__c', 'TM_TOMA__Exercised_Contract_Value__c', 'Business_Area__c',
  'Closeout_Time_Standard__c', 'Finance_Analyst__r.Name', 'ContractAdministrator__r.Name',
  'Contract_Administrator_Email_Id__c', 'Contract_Manager__r.Name', 'Contracting_Officer__r.Name',
  'Contracting_Officer_Email__c', 'Contracts_Director__r.Name', 'Technical_Director__r.Name',
  'Operations_Director__r.Name', 'Program_Area_Lead__r.Name', 'Program_Manager__r.Name',
  'Program_Manager_Email_Id__c', 'Subcontract_Admin__r.Name', 'Subcontract_Manager__c',
  'Contract_Name', 'TM_TOMA__Contract_Type__c', 'name', 'link', 'lastModifiedDateTime',
  'drive_id', 'Project', 'Project_x003a_PCN', 'Contracts_x0020_Subfolder',
];
const OPPORTUNITY_COLUMNS = [
  'Id', 'LastModifiedDate', 'Name', 'Description', 'Capabilities__c', 'Capability_Areas__c',
  'Sub_Capability__c', 'Project_Name__c', 'Business_Area__c', 'StageName', 'Status__c',
  'Proposal_Status__c', 'Amount', 'Pipeline_Total__c', 'Award_Date_Formula__c',
  'FedCapture__Our_Role__c',
];

const entity = ctx.entity;
const allowedColumns = [...(entity === 'opportunities' ? OPPORTUNITY_COLUMNS : CONTRACT_COLUMNS)].sort();
const table = entity === 'opportunities' ? cfg.postgresOpportunitiesTable : cfg.postgresContractsTable;

const system =
  'Create a PostgreSQL query plan, not SQL. Return one JSON object matching: ' +
  '{"entity": string, "columns": [string], "filters": {string: string|number|boolean}, ' +
  '"limit": integer, "order_by": string|null, "descending": boolean, "distinct": boolean, ' +
  '"active_only": boolean, "base_contract_only": boolean, "modified_within_years": integer|null}. ' +
  `The entity must be '${entity}'. Allowed columns: ${JSON.stringify(allowedColumns)}. ` +
  'For a dotted project ID use Project_ID__c; for exactly seven digits use Project. ' +
  'Always return project IDs in filters as JSON strings, never numbers. ' +
  'For project-level properties set distinct=true. For latest modifications use ' +
  "Contracts_x0020_Subfolder='Modifications', order_by=lastModifiedDateTime, descending=true. " +
  'Set active_only only when the user requests active contracts. ' +
  "For 'last N years' document requests, set modified_within_years=N. " +
  'Set base_contract_only only when the user requests base-contract scope. ' +
  'Never invent columns or filters.';

return [{
  json: {
    ...ctx,
    allowedColumns,
    table,
    llmRequest: {
      model: cfg.sqlModel,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: ctx.question },
      ],
      temperature: 0,
    },
  },
}];

// Port of QueryPlanner validation + Workflow.query_contracts overrides + PostgresRepository._build_query.
// Only whitelisted, quoted identifiers reach the SQL text; every value is a bound parameter.
const cfg = $('Config').first().json;
const ctx = $('Build Planner Request').first().json;
const allowed = new Set(ctx.allowedColumns);
const fail = (msg) => { throw new Error(msg); };

let raw;
try {
  const content = String($input.first().json.choices[0].message.content);
  const match = content.replace(/```(?:json)?/gi, '').match(/\{[\s\S]*\}/);
  raw = JSON.parse(match ? match[0] : content);
} catch (e) {
  fail('The SQL planner returned an invalid constrained query plan');
}
if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
  fail('The SQL planner returned an invalid constrained query plan');
}

const plan = {
  entity: raw.entity,
  columns: Array.isArray(raw.columns) ? raw.columns : [],
  filters: raw.filters && typeof raw.filters === 'object' && !Array.isArray(raw.filters) ? raw.filters : {},
  limit: Number.isInteger(raw.limit) && raw.limit > 0 ? raw.limit : 100,
  order_by: raw.order_by ?? null,
  descending: raw.descending === true,
  distinct: raw.distinct === true,
  active_only: raw.active_only === true,
  base_contract_only: raw.base_contract_only === true,
  modified_within_years: Number.isInteger(raw.modified_within_years) && raw.modified_within_years > 0
    ? raw.modified_within_years : null,
};

if (plan.entity !== ctx.entity) fail('The SQL planner returned the wrong query entity');
if (!plan.columns.every((c) => allowed.has(c))) fail('The SQL planner returned unapproved result columns');
if (!Object.keys(plan.filters).every((c) => allowed.has(c))) fail('The SQL planner returned unapproved filters');
if (plan.order_by !== null && !allowed.has(plan.order_by)) fail('The SQL planner returned an unapproved ordering column');
for (const v of Object.values(plan.filters)) {
  if (!['string', 'number', 'boolean'].includes(typeof v)) fail('The SQL planner returned an invalid constrained query plan');
}

// Workflow.query_contracts adjustments for the "SQL then documents" routes.
const docsRoute = ctx.route === 'sql_and_docs_all' || ctx.route === 'sql_and_docs_base';
if (docsRoute) {
  plan.base_contract_only = ctx.baseOnly || plan.base_contract_only;
  if (plan.modified_within_years === null && ctx.recentYears) plan.modified_within_years = ctx.recentYears;
  plan.columns = ['drive_id', 'link', 'name'];
  if (plan.distinct && plan.order_by && !plan.columns.includes(plan.order_by)) plan.columns.push(plan.order_by);
}

const IDENT = /^[A-Za-z_][A-Za-z0-9_.]*$/;
const q = (id) => {
  if (!IDENT.test(id)) fail(`Invalid configured SQL identifier: ${id}`);
  return `"${id}"`;
};

let requested = plan.columns.length ? [...plan.columns] : [...ctx.allowedColumns];
if (plan.distinct && plan.order_by && !requested.includes(plan.order_by)) requested.push(plan.order_by);

const params = [];
const clauses = [];
const isContracts = plan.entity === 'contract_metadata';
for (const [column, value] of Object.entries(plan.filters)) {
  // Salesforce metadata fields are stored as text, including numeric-looking project IDs.
  params.push(isContracts ? String(value) : value);
  clauses.push(`${q(column)} = $${params.length}`);
}
if (isContracts && plan.active_only) clauses.push('"Closeout_Time_Standard__c"::date > CURRENT_DATE');
if (isContracts && plan.base_contract_only) {
  params.push('Base Contract');
  clauses.push(`"Contracts_x0020_Subfolder" = $${params.length}`);
}
if (isContracts && plan.modified_within_years !== null) {
  params.push(plan.modified_within_years);
  clauses.push(`"lastModifiedDateTime"::timestamptz >= CURRENT_DATE - ($${params.length} * INTERVAL '1 year')`);
}

const where = clauses.length ? ` WHERE ${clauses.join(' AND ')}` : '';
const order = plan.order_by ? ` ORDER BY ${q(plan.order_by)} ${plan.descending ? 'DESC' : 'ASC'}` : '';
params.push(Math.min(plan.limit, Number(cfg.maxSqlRows)));
const inner = `SELECT ${plan.distinct ? 'DISTINCT ' : ''}${requested.map(q).join(', ')} ` +
  `FROM ${q(cfg.postgresSchema)}.${q(ctx.table)}${where}${order} LIMIT $${params.length}`;
// Wrap so Postgres always returns exactly one row ({records: [...]}), even when nothing matches.
const sql = `SELECT COALESCE(json_agg(t), '[]'::json) AS records FROM (${inner}) AS t`;

return [{ json: { sql, params, plan } }];

// Unpack the json_agg result and decide whether documents are needed next.
const ctx = $('Resolve Route').first().json;
let records = $input.first().json.records ?? [];
if (typeof records === 'string') records = JSON.parse(records);

return [{
  json: {
    question: ctx.question,
    route: ctx.route,
    needsDocs: ctx.route !== 'sql_only',
    records,
  },
}];

// Port of Workflow._structured_answer + rendering.py (drive_id is never shown to the LLM or caller).
const cfg = $('Config').first().json;
const { question, route, records } = $input.first().json;

function sourcesFromRecords(rows) {
  const seen = new Set();
  const out = [];
  for (const r of rows) {
    const link = r.link;
    if (typeof link !== 'string' || !link) continue;
    const name = String(r.name || r.Contract_Name || link);
    const key = `${name}\u0000${link}`;
    if (!seen.has(key)) { seen.add(key); out.push({ name, link }); }
  }
  return out;
}

const renderRecords = (rows) => rows.map((r) => Object.entries(r)
  .filter(([k, v]) => k !== 'drive_id' && v !== null && v !== undefined)
  .map(([k, v]) => `${k}: ${v instanceof Object ? JSON.stringify(v) : v}`)
  .join(', ')).join('\n');

const sources = sourcesFromRecords(records);
if (!records.length) {
  return [{ json: { route, sources, needsLlm: false, directAnswer: 'No matching records were found.' } }];
}

return [{
  json: {
    route,
    sources,
    needsLlm: true,
    directAnswer: '',
    llmRequest: {
      model: cfg.answerModel,
      messages: [
        {
          role: 'system',
          content: 'Answer only from the supplied structured records. Be concise, include relevant ' +
            'plain-text links, and never expose internal drive IDs.',
        },
        { role: 'user', content: `Question: ${question}\n\nStructured records:\n${renderRecords(records)}` },
      ],
      temperature: 0,
    },
  },
}];

// Port of ChromaClient.search_contracts / search_reference request setup.
const cfg = $('Config').first().json;
const ctx = $('Resolve Route').first().json;
const route = ctx.route;

let fileIds = [];
if (route === 'sql_and_docs_all' || route === 'sql_and_docs_base') {
  fileIds = ($input.first().json.records || [])
    .filter((r) => r.drive_id)
    .map((r) => String(r.drive_id));
}

const filtered = fileIds.length > 0;
const limitedIds = fileIds.slice(0, Number(cfg.maxFileIds));
const collection = route === 'reference_docs' ? cfg.chromaReferenceCollection : cfg.chromaContractCollection;

return [{
  json: {
    question: ctx.question,
    route,
    collection,
    filtered,
    // Filtered searches only need top-K; broad searches pull a large candidate pool for BM25 re-ranking.
    nResults: Number(filtered ? cfg.chromaTopK : cfg.chromaCandidateK),
    where: filtered ? { drive_id: { $in: limitedIds } } : null,
    embeddingModel: cfg.embeddingModel || '',
  },
}];

// Port of chroma/search.py (normalize_results, hybrid_rank_results) + Workflow._grounded_answer.
const cfg = $('Config').first().json;
const search = $('Prepare Chroma Search').first().json;
const results = $input.first().json;
const topK = Number(cfg.chromaTopK);

const documents = (results.documents && results.documents[0]) || [];
const metadatas = (results.metadatas && results.metadatas[0]) || [];
const distances = (results.distances && results.distances[0]) || [];
const isNum = (v) => typeof v === 'number' && Number.isFinite(v);
const metaAt = (i) => (i < metadatas.length && metadatas[i]) ? metadatas[i] : {};

function normalizeResults() {
  return documents.map((doc, i) => {
    const m = metaAt(i);
    const d = i < distances.length ? distances[i] : null;
    return { content: String(doc), name: m.name || m.source || null, link: m.link || null, score: isNum(d) ? 1 - d : null };
  });
}

function hybridRankResults(query, limit) {
  const tokenize = (t) => t.match(/[a-z0-9]{3,}/g) || [];
  const BM25_K1 = 1.5;
  const BM25_B = 0.75;
  const queryTerms = [...new Set(tokenize(query.toLowerCase()))];
  const numeric = distances.filter(isNum);
  const best = numeric.length ? Math.min(...numeric) : 0;
  const worst = numeric.length ? Math.max(...numeric) : best;
  const span = worst - best;
  const n = Math.min(documents.length, metadatas.length);
  const tokenized = [];
  for (let i = 0; i < n; i++) tokenized.push(tokenize(`${(metadatas[i] || {}).name || ''} ${documents[i]}`.toLowerCase()));
  const avgLen = documents.length && tokenized.length ? tokenized.reduce((s, t) => s + t.length, 0) / tokenized.length : 0;
  const df = {};
  for (const term of queryTerms) df[term] = tokenized.filter((t) => t.includes(term)).length;
  const bm25 = tokenized.map((tokens) => {
    let score = 0;
    for (const term of queryTerms) {
      const tf = tokens.filter((t) => t === term).length;
      if (!tf) continue;
      // Same IDF form as the Python implementation (uses the chunk's token count).
      const idf = Math.log(1 + ((tokens.length - df[term] + 0.5) / (df[term] + 0.5)));
      const denom = tf + BM25_K1 * (1 - BM25_B + BM25_B * (tokens.length / avgLen));
      score += idf * (tf * (BM25_K1 + 1) / denom);
    }
    return score;
  });
  const maxBm25 = bm25.length ? Math.max(...bm25) : 0;
  const chunks = documents.map((doc, i) => {
    const m = metaAt(i);
    const d = i < distances.length ? distances[i] : null;
    const semantic = isNum(d) && span ? 1 - ((d - best) / span) : 1.0;
    const b = i < bm25.length ? bm25[i] : 0;
    const keyword = maxBm25 ? b / maxBm25 : 0;
    return {
      content: String(doc), name: m.name || m.source || null, link: m.link || null,
      score: semantic, bm25_score: b, keyword_score: keyword, hybrid_score: (semantic + keyword) / 2,
    };
  });
  return chunks.sort((a, b) => b.hybrid_score - a.hybrid_score).slice(0, limit);
}

const chunks = search.filtered ? normalizeResults() : hybridRankResults(search.question, topK);

// _grounded_answer: one chunk per (name, link), sources with links only.
const unique = [];
const seen = new Set();
for (const c of chunks) {
  const key = `${c.name || ''}\u0000${c.link || ''}`;
  if (!seen.has(key)) { seen.add(key); unique.push(c); }
}
const sources = [];
const seenSrc = new Set();
for (const c of unique) {
  if (typeof c.link !== 'string' || !c.link) continue;
  const name = String(c.name || c.link);
  const key = `${name}\u0000${c.link}`;
  if (!seenSrc.has(key)) { seenSrc.add(key); sources.push({ name, link: c.link }); }
}

const route = search.route;
if (!unique.length) {
  const message = route === 'reference_docs'
    ? "The provided context doesn't cover this."
    : 'No relevant document content was found.';
  return [{ json: { route, sources, needsLlm: false, directAnswer: message } }];
}

const contentLimit = Math.max(400, Math.floor(Number(cfg.maxRagContextChars) / unique.length));
const context = unique.map((c) =>
  `Source: ${c.name || 'document'}\nLink: ${c.link || ''}\nContent: ${String(c.content).slice(0, contentLimit)}`,
).join('\n\n');

return [{
  json: {
    route,
    sources,
    needsLlm: true,
    directAnswer: '',
    llmRequest: {
      model: cfg.answerModel,
      messages: [
        {
          role: 'system',
          content: 'Answer using only the supplied context. Keep the answer to four sentences or fewer. ' +
            'Include relevant plain-text links. Never expose internal drive IDs.',
        },
        { role: 'user', content: `Question: ${search.question}\n\nContext:\n${context}` },
      ],
      temperature: 0,
    },
  },
}];

// llm_only route: answer without internal data.
const cfg = $('Config').first().json;
const ctx = $input.first().json;
return [{
  json: {
    route: ctx.route,
    sources: [],
    needsLlm: true,
    directAnswer: '',
    llmRequest: {
      model: cfg.answerModel,
      messages: [
        { role: 'system', content: 'Answer concisely without claiming to access internal data.' },
        { role: 'user', content: ctx.question },
      ],
      temperature: 0,
    },
  },
}];

// Final API shape, same as the FastAPI Answer model: { answer, route, sources[] }.
const ctx = $('Call LLM?').item.json;
const answer = $json.choices
  ? String($json.choices[0]?.message?.content ?? '')
  : ctx.directAnswer;
return { json: { answer, route: ctx.route, sources: ctx.sources || [] } };
